#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# Full 3-mode overhead campaign on the homogeneous host config
# (host_perf_mode.sh on: 6 P-cores @2.3 GHz, SMT/E-cores/turbo/thermald off).
# Order: Autoware (fishwait10, ~1.5 h) → Isaac 13 benches (overhead_sweep_v4,
# -wip images with client spans + *_fini). host_perf_mode status is logged
# before/after each block so a frequency cap or throttle episode is visible.
# New DEST dirs — the Aug-30/31 campaigns stay untouched (notes refer to them).
set -u
REPO=/home/tue037807/fish_interfere
LOG=$HOME/fish_traces/campaign_pcore_v5.log
DEST_ISAAC=$HOME/fish_traces/overhead_isaac_v5
cd "$REPO"
stamp() { echo "[campaign $(date +%F' '%T)] $*" | tee -a "$LOG"; }
stat_block() { { echo "=== host_perf_mode status ($1) ==="; scripts/host_perf_mode.sh status; } | tee -a "$LOG"; }

stamp "START"
stat_block "campaign start"

stamp "Autoware 3-mode ×3 on fishwait10"
IMG=autoware-dev-trt-a1000-fishwait10:latest REPS=3 \
  bash scripts/autoware_runs/run_overhead_modes.sh 2>&1 | tee -a "$LOG" | grep -E '^\[ovh\]' 
stamp "Autoware rc=${PIPESTATUS[0]}"
stat_block "after Autoware"

stamp "Isaac 13 benches, warmup + 3 modes ×3 → $DEST_ISAAC"
DEST_BASE=$DEST_ISAAC REPS=3 CUDA_EVT=0 \
  bash scripts/overhead_sweep_v4.sh apriltag bi3d bi3d_freespace dnn_image_encoder dope \
    ess image_proc nvblox segformer stereo_image_proc tensor_rt unet visual_slam 2>&1 | tee -a "$LOG" | grep -E '^\[v4' 
stamp "Isaac rc=${PIPESTATUS[0]}"
stat_block "after Isaac"
stamp "DONE"
